code.cpp:
class Solution {
public:
    vector<int> prevPermOpt1(vector<int>& arr) {
        int n = arr.size();
        int i = n - 2;
        while (i >= 0 && arr[i] <= arr[i + 1]) i--;
        if (i < 0) return arr;
        int bestJ = i + 1;
        for (int j = i + 2; j < n; j++) {
            if (arr[j] < arr[i] && arr[j] > arr[bestJ]) {
                bestJ = j;
            }
        }
        swap(arr[i], arr[bestJ]);
        return arr;
    }
};
